local import       = import
local checkNumber  = checkNumber
local FormulaUtils = FormulaUtils
local EquipUtils   = EquipUtils

local EquipDojo          = import('Game.Dojo.EquipDojo')
local CardProgressionMgr = import('Game.CardProgression.CardProgressionMgr')
---@type CardConfMgr
local cardConfMgr               = CardConfMgr:GetInstance()
---@type CardProgressionConstants
local CardProgressionConstants  = import("Game.CardProgression.CardProgressionConstants")
local CardDojo                  = import("Game.Dojo.CardDojo")

---@class CardProgressionEntity
---@field id          number 卡牌数据id 机器人：-1  >0 卡牌id
---@field combatPower number 战力
---@field cardDojo    CardDojo 卡牌数据
---@field equipPart2Dojo table<number, EquipDojo> 装备部位对应数据
local CardProgressionEntity = Class("CardProgressionEntity")

function CardProgressionEntity:__init()
    self.playerCardId   = -1    --- 卡牌数据id 机器人：-1  >0 卡牌id
    self.combatPower    = 0     --- 战力
    self.cardDojo       = nil   --- 卡牌数据
    self.equipPart2Dojo = nil   --- 装备部位对应数据
    self.isEntity       = true
    self.isIgnoreGlobal = false --- 是否忽略全局属性加成
    self.additionMap    = nil   --- 自定义属性加成map（key：属性id，value：加成系数）
end

function CardProgressionEntity:__delete()
    self.playerCardId   = -1    --- 卡牌数据id 机器人：-1  >0 卡牌id
    self.combatPower    = 0     --- 战力
    self.cardDojo       = nil   --- 卡牌数据
    self.equipPart2Dojo = nil   --- 装备部位对应数据
    self.isIgnoreGlobal = nil
    self.additionMap    = nil
end

--- FillByCardDojo
--- 通过CardDojo 填充数据
---@param cardDojo CardDojo
function CardProgressionEntity:FillByCardDojo(cardDojo)
    self.playerCardId   = checkNumber(cardDojo.id)
    self.cardDojo       = cardDojo   
    self.equipPart2Dojo = CardProgressionEntity.GenerateEquipPart2DojoByCardDojo(cardDojo)
    self.cardId         = checkNumber(cardDojo.cardId)
    self.rare           = cardDojo:GetRare()
    self.totalStar      = checkNumber(cardDojo.star) + checkNumber(cardDojo.superStar)

    self._isNeedResetSort = true
    self._isNeedRestFilter = true
    return self
end


--- 是否为纯净卡，忽略全局属性加成，忽略皮肤加成
---@param isPureCard boolean 
function CardProgressionEntity:FillPureCard(isPureCard)
    self.isIgnoreGlobal = isPureCard
    self.cardSkin2Lv    = {}
    return self
end


--- 自定义属性加成系数
---@param additionMap table @ 属性加成map（key：属性id，value：加成系数）
function CardProgressionEntity:FillAdditionMap(additionMap)
    self.additionMap = additionMap
    return self
end


--- FillByRobot
--- 通过机器人数据 填充数据
---@param robotData table
function CardProgressionEntity:FillByRobot(robotData)
    self.playerCardId   = -1
    self.cardDojo       = CardDojo.New()
    self.cardDojo:Fill(robotData)
    self.equipPart2Dojo = CardProgressionEntity.GenerateEquipPart2DojoByRobot(robotData)
    self.cardId         = checkNumber(robotData.cardId)
    self.rare           = cardConfMgr:GetCardRareByCardId(self.cardId, robotData.advanceLevel)
    self.totalStar      = checkNumber(robotData.star) + checkNumber(robotData.superStar)

    self.cardSkin2Lv    = robotData.cardSkinId2Lv
    self._isNeedResetSort = true
    self._isNeedRestFilter = true
    return self
end

--- GenerateEquipPart2DojoByCardDojo
--- 根据 CardDojo 生成 装备部位对应数据
---@param cardDojo CardDojo
function CardProgressionEntity.GenerateEquipPart2DojoByCardDojo(cardDojo)
    ---@type CardProgressionMgr
    local cardProgressionMgr = CardProgressionMgr:GetInstance()
    ---@type EquipmentComponent
    local equipComp          = cardProgressionMgr:GetEquipmentComp()
    local equipPart2Dojo = {}
    local MaxEquipCount = CardProgressionConstants.EquipmentNum
    for part = 1, MaxEquipCount, 1 do
        --- equipment .. i
        local key = EquipUtils.GetEquipIdKeyByPart(part)
        --- cardDojo[equipment .. i]
        local playerEquipmentId = cardDojo[key]

        ---@type EquipDojo
        local equipDojo = equipComp:GetEquipById(playerEquipmentId)
        equipPart2Dojo[part] = equipDojo
    end

    return equipPart2Dojo

end

--- GenerateEquipPart2DojoByRobot
--- 根据 robotData 生成 装备部位对应数据
---@param cardDojo CardDojo
function CardProgressionEntity.GenerateEquipPart2DojoByRobot(robotData)
    --- 对于机器人来说 返回的直接是装备数据
    local equipPart2Dojo = {}
    local MaxEquipCount = CardProgressionConstants.EquipmentNum
    for part = 1, MaxEquipCount, 1 do
        --- equipment .. i
        local key = EquipUtils.GetEquipIdKeyByPart(part)
        --- robotData[equipment .. i]
        local equipmentData = robotData[key]
        ---@type EquipDojo
        local equipDojo = EquipDojo.New()
        equipDojo:Fill(equipmentData)
        equipPart2Dojo[part] = equipDojo

    end

    return equipPart2Dojo

end


function CardProgressionEntity:InitSortField(signboardId, attrProvider2AttrAddId2V, providerCombatEff2AddTypeConfig)
    if not self._isNeedResetSort then
        return
    end
    self._isNeedResetSort   = false
    
    local cardDojo      = self.cardDojo
    self.combatPower    = FormulaUtils.CalcCardCombatEffectiveness(self, {specifyAttrProvider2AttrAddId2v = attrProvider2AttrAddId2V, specifyProviderCombatEff2AddTypeConfig = providerCombatEff2AddTypeConfig})
    self.cardLevel      = checkNumber(cardDojo.cardLevel)
    self.id             = checkNumber(cardDojo.id)
    self.signboard      = signboardId == self.id and 1 or 0
    ---@type CardVo
    local vo = cardConfMgr:GetCardByRefId(self.cardId)
    self.initRare        = vo.rare
end

function CardProgressionEntity:InitFilterField()
    if not self._isNeedRestFilter then
        return
    end
    self._isNeedRestFilter   = false

    ---@type CardVo
    local vo = cardConfMgr:GetCardByRefId(self.cardId)
    self.attributeType = vo.attributeType
    self.race          = vo.race
    self.career        = vo.career

end

return CardProgressionEntity